import React from "react";

interface RunAllTestsButtonProps {
  isRunning: boolean;
  onClick: () => void;
}

export const RunAllTestsButton: React.FC<RunAllTestsButtonProps> = ({
  isRunning,
  onClick,
}) => {
  return (
    <button
      onClick={onClick}
      disabled={isRunning}
      style={{
        color: "#fff",
        backgroundColor: isRunning ? "#ccc" : "#007bff",
        cursor: isRunning ? "not-allowed" : "pointer",
      }}
    >
      {isRunning ? "Running Tests..." : "Run All Tests"}
    </button>
  );
};

interface OnboardButtonProps {
  mnemonic: string;
  baseURL: string;
  onboardLoading: boolean;
  isRunning: boolean;
  onOnboard: (mnemonic: string, baseURL: string) => void;
}

export const OnboardButton: React.FC<OnboardButtonProps> = ({
  mnemonic,
  baseURL,
  onboardLoading,
  isRunning,
  onOnboard,
}) => {
  const isDisabled =
    onboardLoading || isRunning || !mnemonic || mnemonic.trim() === "";

  return (
    <button
      onClick={() => {
        if (mnemonic && mnemonic.trim() !== "") {
          onOnboard(mnemonic, baseURL);
        }
      }}
      disabled={isDisabled}
      style={{
        color: isDisabled ? "#ccc" : "#fff",
        backgroundColor: isDisabled ? "#ccc" : "#28a745",
        cursor: isDisabled ? "not-allowed" : "pointer",
      }}
    >
      {onboardLoading ? "Running Authentication Flow..." : "Authentication Flow"}
    </button>
  );
};

