interface FiClientTestButtonProps {
  mnemonic: string;
  isRunning: boolean;
  isLoading: boolean;
  onClick: () => void;
}

export const FiClientTestButton: React.FC<FiClientTestButtonProps> = ({
  mnemonic,
  isRunning,
  isLoading,
  onClick,
}) => {
  const isMnemonicValid = mnemonic && mnemonic.trim() !== "";
  const isDisabled = isLoading || isRunning || !isMnemonicValid;

  return (
    <button
      onClick={() => {
        if (isMnemonicValid) {
          onClick();
        }
      }}
      disabled={isDisabled}
      style={{
        color: isDisabled ? "#ccc" : "#fff",
        backgroundColor: isDisabled ? "#ccc" : "#e83e8c",
        cursor: isDisabled ? "not-allowed" : "pointer",
      }}
      title={!isMnemonicValid ? "Mnemonic is required for Fi Client tests" : ""}
    >
      {isLoading ? "Running Fi Client Tests..." : "Fi Client Test"}
    </button>
  );
};

